def f(g):
    H,W=len(g),len(g[0]); O=[r[:] for r in g]
    runs=[]
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]!=0:
                v=g[r][c]; s=c
                while c<W and g[r][c]==v: c+=1
                runs.append((r,s,v,c-s))
            else: c+=1
    for sr in range(H):
        for sc in range(W):
            v=g[sr][sc]
            if v==0: continue
            ref=[p for p in runs if p[2]==v and not (p[0]==sr and p[1]<=sc<p[1]+p[3])]
            if not ref: continue
            R=max(ref,key=lambda p:p[3])
            _,s,n=R[1],R[3],R[2]
            idx=(sc-s)%n
            lo=sc-idx
            for k in range(-n,n+1):
                j=lo+k
                if 0<=j<W and O[sr][j]==0:
